BEGIN;

CREATE TABLE IF NOT EXISTS public.help_categories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  name text NOT NULL CHECK (length(name) BETWEEN 2 AND 100),
  description text NOT NULL DEFAULT '',
  icon_key text NOT NULL DEFAULT 'help-circle',
  sort_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.help_subcategories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  category_id uuid NOT NULL REFERENCES public.help_categories(id) ON DELETE RESTRICT,
  slug text NOT NULL UNIQUE,
  name text NOT NULL CHECK (length(name) BETWEEN 2 AND 120),
  kind text NOT NULL CHECK (kind IN ('topic','master_group')),
  source_specs text[] NOT NULL DEFAULT ARRAY[]::text[],
  sort_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.help_articles (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  slug text NOT NULL UNIQUE,
  category_id uuid NOT NULL REFERENCES public.help_categories(id) ON DELETE RESTRICT,
  question text NOT NULL CHECK (length(question) BETWEEN 8 AND 180),
  excerpt text NOT NULL DEFAULT '' CHECK (length(excerpt) <= 360),
  answer_markdown text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','fact_check','approval','published','unpublished','archived')),
  featured boolean NOT NULL DEFAULT false,
  source_reference text NOT NULL DEFAULT '',
  locale text NOT NULL DEFAULT 'en',
  search_vector tsvector GENERATED ALWAYS AS (
    setweight(to_tsvector('english',coalesce(question,'')),'A') ||
    setweight(to_tsvector('english',coalesce(excerpt,'')),'B') ||
    setweight(to_tsvector('english',coalesce(answer_markdown,'')),'C')
  ) STORED,
  author_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  reviewer_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  approver_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  publisher_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  published_at timestamptz,
  last_reviewed_at timestamptz,
  review_due_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (status <> 'published' OR (published_at IS NOT NULL AND length(answer_markdown) > 0))
);

CREATE TABLE IF NOT EXISTS public.help_article_subcategories (
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  subcategory_id uuid NOT NULL REFERENCES public.help_subcategories(id) ON DELETE RESTRICT,
  sort_order integer NOT NULL DEFAULT 0,
  PRIMARY KEY (article_id,subcategory_id)
);

CREATE TABLE IF NOT EXISTS public.help_article_translations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  locale text NOT NULL CHECK (length(locale) BETWEEN 2 AND 20),
  question text NOT NULL,
  excerpt text NOT NULL DEFAULT '',
  answer_markdown text NOT NULL DEFAULT '',
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','review','fact_check','approval','published','untranslated')),
  translator_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  reviewer_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  published_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (article_id,locale)
);

CREATE TABLE IF NOT EXISTS public.help_keywords (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  keyword text NOT NULL UNIQUE CHECK (length(keyword) BETWEEN 2 AND 80),
  normalized_keyword text NOT NULL UNIQUE,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.help_article_keywords (
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  keyword_id uuid NOT NULL REFERENCES public.help_keywords(id) ON DELETE CASCADE,
  PRIMARY KEY (article_id,keyword_id)
);

CREATE TABLE IF NOT EXISTS public.help_related_articles (
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  related_article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  sort_order integer NOT NULL DEFAULT 0,
  PRIMARY KEY (article_id,related_article_id),
  CHECK (article_id <> related_article_id)
);

CREATE TABLE IF NOT EXISTS public.help_article_feedback (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  helpful boolean NOT NULL,
  reason text NOT NULL DEFAULT '' CHECK (length(reason) <= 600),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (article_id,user_id)
);

CREATE TABLE IF NOT EXISTS public.help_article_revisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  revision_no integer NOT NULL CHECK (revision_no > 0),
  content_snapshot jsonb NOT NULL,
  changed_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  revision_note text NOT NULL DEFAULT '',
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (article_id,revision_no)
);

CREATE TABLE IF NOT EXISTS public.help_article_bookmarks (
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (article_id,user_id)
);

CREATE TABLE IF NOT EXISTS public.help_article_views (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  viewed_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.help_article_assets (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id uuid NOT NULL REFERENCES public.help_articles(id) ON DELETE CASCADE,
  asset_type text NOT NULL CHECK (asset_type IN ('image','video')),
  storage_bucket text NOT NULL DEFAULT 'minglora-help-center',
  storage_path text NOT NULL CHECK (storage_path !~ '(^/|\.\.|\\)'),
  alt_text text NOT NULL DEFAULT '',
  caption text NOT NULL DEFAULT '',
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (storage_bucket,storage_path)
);

CREATE TABLE IF NOT EXISTS public.help_search_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
  search_query text NOT NULL CHECK (length(search_query) BETWEEN 1 AND 120),
  results_count integer NOT NULL DEFAULT 0 CHECK (results_count >= 0),
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS help_subcategories_category_sort_idx ON public.help_subcategories(category_id,sort_order) WHERE active=true;
CREATE INDEX IF NOT EXISTS help_articles_published_category_idx ON public.help_articles(category_id,published_at DESC) WHERE status='published';
CREATE INDEX IF NOT EXISTS help_articles_search_gin_idx ON public.help_articles USING gin(search_vector) WHERE status='published';
CREATE INDEX IF NOT EXISTS help_articles_updated_idx ON public.help_articles(updated_at DESC) WHERE status='published';
CREATE INDEX IF NOT EXISTS help_article_subcategories_subcategory_idx ON public.help_article_subcategories(subcategory_id,sort_order);
CREATE INDEX IF NOT EXISTS help_article_feedback_article_idx ON public.help_article_feedback(article_id,helpful);
CREATE INDEX IF NOT EXISTS help_article_views_article_date_idx ON public.help_article_views(article_id,viewed_at DESC);
CREATE INDEX IF NOT EXISTS help_article_views_user_date_idx ON public.help_article_views(user_id,viewed_at DESC) WHERE user_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS help_search_events_date_idx ON public.help_search_events(created_at DESC);

ALTER TABLE public.help_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_subcategories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_subcategories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_translations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_keywords ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_keywords ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_related_articles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_feedback ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_bookmarks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_views ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_article_assets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.help_search_events ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.help_categories,public.help_subcategories,public.help_articles,
 public.help_article_subcategories,public.help_article_translations,public.help_keywords,
 public.help_article_keywords,public.help_related_articles,public.help_article_feedback,
 public.help_article_revisions,public.help_article_bookmarks,public.help_article_views,
 public.help_article_assets,public.help_search_events FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.help_categories,public.help_subcategories,public.help_articles,
 public.help_article_subcategories,public.help_article_translations,public.help_related_articles,
 public.help_article_assets TO anon,authenticated;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.help_article_feedback,public.help_article_bookmarks,
 public.help_article_views,public.help_search_events TO authenticated;
GRANT ALL ON public.help_categories,public.help_subcategories,public.help_articles,
 public.help_article_subcategories,public.help_article_translations,public.help_keywords,
 public.help_article_keywords,public.help_related_articles,public.help_article_feedback,
 public.help_article_revisions,public.help_article_bookmarks,public.help_article_views,
 public.help_article_assets,public.help_search_events TO service_role;

CREATE POLICY help_categories_public_read ON public.help_categories
 FOR SELECT TO anon,authenticated USING (active=true);
CREATE POLICY help_subcategories_public_read ON public.help_subcategories
 FOR SELECT TO anon,authenticated USING (active=true AND EXISTS(
   SELECT 1 FROM public.help_categories c WHERE c.id=category_id AND c.active=true
 ));
CREATE POLICY help_articles_public_read ON public.help_articles
 FOR SELECT TO anon,authenticated USING (status='published');
CREATE POLICY help_article_subcategories_public_read ON public.help_article_subcategories
 FOR SELECT TO anon,authenticated USING (EXISTS(
   SELECT 1 FROM public.help_articles a WHERE a.id=article_id AND a.status='published'
 ));
CREATE POLICY help_article_translations_public_read ON public.help_article_translations
 FOR SELECT TO anon,authenticated USING (status='published' AND EXISTS(
   SELECT 1 FROM public.help_articles a WHERE a.id=article_id AND a.status='published'
 ));
CREATE POLICY help_related_articles_public_read ON public.help_related_articles
 FOR SELECT TO anon,authenticated USING (
   EXISTS(SELECT 1 FROM public.help_articles a WHERE a.id=article_id AND a.status='published')
   AND EXISTS(SELECT 1 FROM public.help_articles r WHERE r.id=related_article_id AND r.status='published')
 );
CREATE POLICY help_article_assets_public_read ON public.help_article_assets
 FOR SELECT TO anon,authenticated USING (EXISTS(
   SELECT 1 FROM public.help_articles a WHERE a.id=article_id AND a.status='published'
 ));
CREATE POLICY help_article_feedback_own_select ON public.help_article_feedback
 FOR SELECT TO authenticated USING ((select auth.uid())=user_id);
CREATE POLICY help_article_feedback_own_insert ON public.help_article_feedback
 FOR INSERT TO authenticated WITH CHECK ((select auth.uid())=user_id AND EXISTS(
   SELECT 1 FROM public.help_articles a WHERE a.id=article_id AND a.status='published'
 ));
CREATE POLICY help_article_feedback_own_update ON public.help_article_feedback
 FOR UPDATE TO authenticated USING ((select auth.uid())=user_id)
 WITH CHECK ((select auth.uid())=user_id);
CREATE POLICY help_article_bookmarks_own ON public.help_article_bookmarks
 FOR ALL TO authenticated USING ((select auth.uid())=user_id)
 WITH CHECK ((select auth.uid())=user_id);
CREATE POLICY help_article_views_own ON public.help_article_views
 FOR ALL TO authenticated USING ((select auth.uid())=user_id)
 WITH CHECK ((select auth.uid())=user_id);
CREATE POLICY help_search_events_own ON public.help_search_events
 FOR INSERT TO authenticated WITH CHECK ((select auth.uid())=user_id);

