('messenger','Messenger','Private conversations, attachments and messaging controls.','message-circle',9),
('voice-video-calls','Voice & Video Calls','Call setup, permissions, controls and privacy.','phone-call',10),
('groups-pages','Groups & Pages','Community groups, Pages, roles and moderation.','users-round',11),
