('creator-features','Creator Features','Creator tools, Creator Studio and audience features.','sparkles',13),
('gifts-coins','Gifts & Coins','Coin balances, virtual gifts and gift transactions.','gift',14),
('creator-earnings-payouts','Creator Earnings & Payouts','Earnings statements, payout eligibility and payment support.','wallet',15),
('meetwave','MeetWave','Meetings, hosts, guests and supported screen layouts.','video',16),
