INSERT INTO public.help_subcategories(category_id,slug,name,kind,source_specs,sort_order)
SELECT c.id,s.slug,s.name,s.kind,s."sourceSpecs",
       row_number() OVER(PARTITION BY c.id ORDER BY s.kind,s.slug)::integer
FROM seed s JOIN public.help_categories c ON c.slug=s."categorySlug"
ON CONFLICT(slug) DO UPDATE SET
 category_id=EXCLUDED.category_id,name=EXCLUDED.name,kind=EXCLUDED.kind,
 source_specs=EXCLUDED.source_specs,sort_order=EXCLUDED.sort_order,updated_at=now();

COMMIT;
